CREATE TABLE payments_stage (
  payment_id   NUMBER PRIMARY KEY,
  amount_text  VARCHAR2(20)
);

INSERT INTO payments_stage VALUES (1, '100');
INSERT INTO payments_stage VALUES (2, '250.50');
INSERT INTO payments_stage VALUES (3, '1,200');
INSERT INTO payments_stage VALUES (4, 'N/A');
INSERT INTO payments_stage VALUES (5, NULL);
INSERT INTO payments_stage VALUES (6, '75');

CREATE TABLE orders (
  order_id   NUMBER PRIMARY KEY,
  order_ref  VARCHAR2(20),
  amount     NUMBER(10,2)
);

INSERT INTO orders VALUES (1, '1001',   500);
INSERT INTO orders VALUES (2, '1002',   320);
INSERT INTO orders VALUES (3, 'WEB-77', 150);

COMMIT;

SELECT payment_id, amount_text
  FROM payments_stage
 WHERE VALIDATE_CONVERSION(amount_text AS NUMBER) = 0;

SELECT payment_id, amount_text
  FROM payments_stage
 WHERE NOT REGEXP_LIKE(amount_text, '^[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)$');

SELECT order_id, amount
  FROM orders
 WHERE order_ref = 1001;

SELECT order_id, amount
  FROM orders
 WHERE order_ref = '1001';

SELECT payment_id
  FROM payments_stage
 WHERE TO_NUMBER(amount_text DEFAULT NULL ON CONVERSION ERROR) > 90;

SELECT TO_NUMBER('250.50', '9999D99',
                 'NLS_NUMERIC_CHARACTERS = ''.,''') AS amount
  FROM dual;

DECLARE
  v_total NUMBER;
BEGIN
  SELECT SUM(TO_NUMBER(amount_text))
    INTO v_total
    FROM payments_stage;
EXCEPTION
  WHEN INVALID_NUMBER THEN
    DBMS_OUTPUT.PUT_LINE('Bad amount in payments_stage: ' || SQLERRM);
    RAISE;
END;
/
